"""Portable scientific figures; no synthetic protein geometry or invented values."""
import json,csv
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.ticker import MaxNLocator
from matplotlib.lines import Line2D
from prepare import ROOT
VIOLET='#6336A7';INK='#16161A';BLUE='#2B6DA6';GRAY='#B6B2BA'
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.labelsize':10,'axes.titlesize':11,'xtick.labelsize':10,'ytick.labelsize':10,'legend.fontsize':10,'pdf.fonttype':42,'svg.fonttype':'none','axes.spines.top':False,'axes.spines.right':False,'axes.linewidth':.6,'savefig.facecolor':'white','text.color':INK,'axes.labelcolor':INK,'xtick.color':INK,'ytick.color':INK})

def save(fig,name):
    for ext in ['svg','pdf','png']:fig.savefig(ROOT/f'figures/{name}.{ext}',dpi=180)
    plt.close(fig)

def main():
    (ROOT/'figures').mkdir(exist_ok=True);m=np.load(ROOT/'model/static-model.npz');ev=json.loads((ROOT/'evaluation/evaluation.json').read_text());p=np.load(ROOT/'results/biquadratic-d2-n33-e4.npz');r=m['r0'];top=p['order'][:5];rec=m['receiver']
    # Exact report-panel footprint, 493 by 220 points. All type is at least 10 pt.
    fig=plt.figure(figsize=(493/72,220/72));ax=fig.add_axes([.00,.06,.40,.88],projection='3d');ax.plot(*r.T,color=GRAY,lw=1,alpha=.9);ax.scatter(*r[rec].T,s=16,color=BLUE,depthshade=False);ax.scatter(*r[top].T,s=40,color=VIOLET,edgecolor='white',linewidth=.5,depthshade=False);ax.set_box_aspect(np.ptp(r,axis=0));ax.view_init(elev=22,azim=-54);ax.set_axis_off();ax.set_title('a   KRAS4B, residues 1–166',loc='left',pad=0)
    fig.legend(handles=[Line2D([],[],marker='o',ls='',color=VIOLET,label='Top five'),Line2D([],[],marker='o',ls='',color=BLUE,label='GDP receiver')],loc='lower left',bbox_to_anchor=(.01,.005),ncol=2,frameon=False,columnspacing=.8,handletextpad=.3)
    ax=fig.add_axes([.69,.15,.275,.70]);short={'Biquadratic d2 grid':'Biquadratic, d = 2','Harmonic d2 same grid':'Harmonic, d = 2','Distance-Hookean d2 same grid':'Hookean, d = 2','Harmonic all 492 modes':'Harmonic, d = 492','Equilibrium d2 biquadratic':'Equilibrium, d = 2','Equilibrium all-mode harmonic':'Equilibrium, d = 492','Graph heat kernel':'Graph diffusion','Contact degree':'Contact degree','Receiver inverse distance':'Inverse distance','Ohm pinned upstream':'Ohm'}
    rows=ev['methods'];y=np.arange(len(rows));counts=[x['hits_at_5A'] for x in rows];colors=[VIOLET]+[GRAY]*(len(rows)-1);ax.barh(y,counts,height=.46,color=colors);ax.set_yticks(y,[short[x['method']] for x in rows]);ax.invert_yaxis();ax.set_xlim(0,5.3);ax.set_xticks([0,1,2,3,4,5]);ax.set_xlabel('Top-five contacts within 5 Å',labelpad=5);ax.tick_params(axis='y',length=0,pad=5);ax.spines['left'].set_visible(False);ax.spines['bottom'].set_color(GRAY)
    for yy,c in zip(y,counts):ax.text(c+.1,yy,f'{c}/5',ha='left',va='center',fontsize=10)
    fig.text(.425,.94,'b   Same candidate set; 6OIM reference',fontsize=11,ha='left',va='top');save(fig,'kras-pilot-overview')
    # Full matrix is preserved as a standalone figure, with a symmetric signed scale.
    fig,ax=plt.subplots(figsize=(6.2,5.3));v=float(np.max(np.abs(p['C'])));im=ax.imshow(p['C'],origin='lower',extent=(.5,166.5,.5,166.5),cmap='PuOr_r',vmin=-v,vmax=v,interpolation='nearest');ax.set_xlabel('Sender residue, KRAS4B numbering');ax.set_ylabel('Receiver residue, KRAS4B numbering');ax.set_title('Fixed-quartic response on two retained modes',loc='left');cb=fig.colorbar(im,ax=ax,shrink=.83);cb.set_label('Dimensionless signed response C');fig.tight_layout(pad=1.2);save(fig,'kras-response-matrix')
    fig,axes=plt.subplots(1,2,figsize=(6.85,3.6));fine=np.load(ROOT/'results/biquadratic-d2-n65-e4.npz')['C'];ns=[17,33,65];err=[float(np.max(np.abs(np.load(ROOT/f'results/biquadratic-d2-n{n}-e4.npz')['C']-fine))) for n in ns];axes[0].plot(ns[:2],err[:2],'-o',color=VIOLET);axes[0].set_xticks(ns);axes[0].set_xlabel('Grid values per coordinate');axes[0].set_ylabel('Maximum |ΔC| versus 65-point grid');axes[0].set_title('a   Grid refinement',loc='left');axes[0].ticklabel_format(axis='y',style='sci',scilimits=(0,0));axes[0].text(.02,.92,'Top five are unchanged.',transform=axes[0].transAxes,va='top',fontsize=10)
    comp=ev['harmonic_coordinate_compression'];dims=[x['d'] for x in comp[:-1]];errors=[x['candidate_to_receiver_max_abs_C_difference'] for x in comp[:-1]];axes[1].plot(dims,errors,'-o',color=VIOLET);axes[1].axhline(.002,color=INK,lw=.8,ls='--');axes[1].set_xscale('log',base=2);axes[1].set_yscale('log');axes[1].set_xticks([1,2,4,8,16,32,64],[1,2,4,8,16,32,64]);axes[1].set_xlabel('Retained harmonic modes');axes[1].set_ylabel('Maximum |ΔC| versus 492 modes');axes[1].set_title('b   Coordinate omission',loc='left');axes[1].text(.03,.13,'Required: ≤0.002',transform=axes[1].transAxes,fontsize=10);fig.tight_layout(pad=1.25,w_pad=2);save(fig,'kras-resolution-and-compression')
    # Rank profiles report the matched candidate domain and preserve reference labels.
    fig,ax=plt.subplots(figsize=(7.1,3.5));score=p['score'];ax.plot(m['canonical'],score,color=VIOLET,lw=1);ax.scatter(m['canonical'][top],score[top],color=VIOLET,s=28);ax.scatter(m['canonical'][rec],np.zeros(len(rec)),marker='|',s=70,color=BLUE);labels=np.load(ROOT/'evaluation/reference-mapping.npz')['contact'];ax.scatter(m['canonical'][labels],np.full(labels.sum(),-.06*score.max()),marker='|',s=70,color=INK);ax.set_xlim(0,167);ax.set_ylim(-.12*score.max(),1.14*score.max());ax.set_xlabel('KRAS4B residue number');ax.set_ylabel('Receiver-RMS score');ax.ticklabel_format(axis='y',style='sci',scilimits=(0,0));ax.set_title('The two-mode shortlist clusters in switch II',loc='left');fig.tight_layout(pad=1.2);save(fig,'kras-residue-scores')
    (ROOT/'figures/figure-captions.md').write_text('''# Figure captions\n\n**KRAS pilot overview.** Panel a shows the observed alpha-carbon trace of 4OBE chain A, restricted to KRAS4B residues 1–166. Violet markers identify the five primary candidates (60, 69, 62, 61 and 65). Blue markers identify the 18 residues contacting GDP in the input structure. GDP is excluded from the mechanical model. Panel b reports contact counts for five selected residues from the same candidate set. A hit requires a mapped heavy atom within 5 Å of MOV in 6OIM. The reference differs from the input at G12C, C51S, C80L and C118S. The comparison is retrospective. Equal contact counts do not establish equivalent predictive performance.\n\n**Response matrix.** The 166 × 166 matrix preserves the dimensionless signed response at one slow-mode relaxation time. Both retained modes use the full biquadratic energy; all 492 harmonic modes define the common standard deviations of the same quartic observables. The color scale is symmetric about zero. This is a reduced-coordinate result, not a complete protein-dynamics calculation.\n\n**Resolution and compression.** Panel a compares the full response matrix with the finest predeclared 65-point grid, at fixed bounds of ±4 slow-mode standard deviations. The final point has zero reference difference and is omitted from the line. Panel b compares the candidate-to-functional-receiver block of analytic harmonic responses with the exact 492-mode harmonic reference, using the same quartic observables and common normalizers. The dashed line marks the 0.002 engineering tolerance. Grid convergence does not compensate for the failure of coordinate compression.\n\n**Residue score profile.** The violet line is the primary receiver-RMS score. Markers identify the five selected eligible residues. Blue ticks mark functional-receiver residues; black ticks below zero mark reference MOV contacts. Negative tick positions are graphical offsets and are not negative scores.\n''')

if __name__=='__main__':main()
